def minPath(grid: list[list[int]], k: int) -> list[int]:
    n = len(grid)
    # best[r][c] holds the lexicographically smallest value list of the
    # current length that starts at cell (r, c).
    best = [[[grid[r][c]] for c in range(n)] for r in range(n)]

    for _ in range(k - 1):
        new_best = [[None] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                candidate = None
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < n and 0 <= nc < n:
                        if candidate is None or best[nr][nc] < candidate:
                            candidate = best[nr][nc]
                new_best[r][c] = [grid[r][c]] + candidate
        best = new_best

    result = None
    for r in range(n):
        for c in range(n):
            if result is None or best[r][c] < result:
                result = best[r][c]
    return result

