def minPath(grid: list[list[int]], k: int) -> list[int]:
    n = len(grid)

    # Locate the cell holding the value 1. Every optimal path starts there,
    # since 1 is the smallest possible first value.
    r, c = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r, c = i, j

    result = []
    for step in range(k):
        result.append(grid[r][c])
        if step == k - 1:
            break
        # Values are unique, so the smallest neighbour is the unique greedy choice.
        best_r, best_c = None, None
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                if best_r is None or grid[nr][nc] < grid[best_r][best_c]:
                    best_r, best_c = nr, nc
        r, c = best_r, best_c

    return result

