def minPath(grid: list[list[int]], k: int) -> list[int]:
    n = len(grid)

    def neighbours(r: int, c: int):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                yield nr, nc

    # best[r][c] holds the lexicographically smallest value list of the
    # current length that starts at cell (r, c).
    best = [[[grid[r][c]] for c in range(n)] for r in range(n)]

    for _ in range(k - 1):
        new_best = [[None] * n for _ in range(n)]
        for r in range(n):
            for c in range(n):
                smallest_tail = min(best[nr][nc] for nr, nc in neighbours(r, c))
                new_best[r][c] = [grid[r][c]] + smallest_tail
        best = new_best

    return min(best[r][c] for r in range(n) for c in range(n))

