def file_name_check(name: str) -> str:
    # Rule 1: at most three digits in total
    digit_count = sum(1 for c in name if c in "0123456789")
    if digit_count > 3:
        return "No"

    # Rule 2: exactly one dot
    if name.count(".") != 1:
        return "No"

    prefix, suffix = name.split(".")

    # Rule 3: prefix non-empty and starts with an ASCII Latin letter
    if not prefix or not (("a" <= prefix[0] <= "z") or ("A" <= prefix[0] <= "Z")):
        return "No"

    # Rule 4: suffix must be exactly one of the allowed extensions
    if suffix not in ("txt", "exe", "dll"):
        return "No"

    return "Yes"

