def do_algebra(operators: list[str], operands: list[int]) -> int:
    values = list(operands)
    ops = list(operators)

    def apply(op: str, a: int, b: int) -> int:
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "//":
            return a // b
        if op == "**":
            return a ** b
        raise ValueError(f"Unsupported operator: {op!r}")

    # Pass 1: exponentiation, right-associative (process right to left).
    i = len(ops) - 1
    while i >= 0:
        if ops[i] == "**":
            values[i] = apply("**", values[i], values[i + 1])
            del values[i + 1]
            del ops[i]
        i -= 1

    # Pass 2: multiplication and floor division, left-associative.
    i = 0
    while i < len(ops):
        if ops[i] in ("*", "//"):
            values[i] = apply(ops[i], values[i], values[i + 1])
            del values[i + 1]
            del ops[i]
        else:
            i += 1

    # Pass 3: addition and subtraction, left-associative.
    i = 0
    while i < len(ops):
        if ops[i] in ("+", "-"):
            values[i] = apply(ops[i], values[i], values[i + 1])
            del values[i + 1]
            del ops[i]
        else:
            i += 1

    return int(values[0])

