def do_algebra(operators: list[str], operands: list[int]) -> int:
    if len(operands) != len(operators) + 1:
        raise ValueError("operands must have length len(operators) + 1")

    ops = list(operators)
    vals = list(operands)
    n_ops = len(ops)

    def parse_power(p: int) -> tuple[int, int]:
        # Right-associative chain: vals[p] ** vals[p+1] ** ... 
        # Returns (value, index of next non-"**" operator).
        q = p
        chain = [vals[p]]
        while q < n_ops and ops[q] == "**":
            q += 1
            chain.append(vals[q])
        result = chain[-1]
        for base in reversed(chain[:-1]):
            result = base ** result
        return result, q

    def parse_term(p: int) -> tuple[int, int]:
        # Handles "*" and "//" (left-associative), operating on powers.
        value, q = parse_power(p)
        while q < n_ops and ops[q] in ("*", "//"):
            op = ops[q]
            rhs, q = parse_power(q + 1)
            if op == "*":
                value = value * rhs
            else:
                value = value // rhs
        return value, q

    def parse_expr() -> int:
        # Handles "+" and "-" (left-associative), operating on terms.
        value, q = parse_term(0)
        while q < n_ops and ops[q] in ("+", "-"):
            op = ops[q]
            rhs, q = parse_term(q + 1)
            if op == "+":
                value = value + rhs
            else:
                value = value - rhs
        return value

    return parse_expr()

