def do_algebra(operators: list[str], operands: list[int]) -> int:
    if len(operands) != len(operators) + 1:
        raise ValueError("operands must have exactly one more element than operators")
    for op in operators:
        if op not in ("+", "-", "*", "//", "**"):
            raise ValueError(f"unsupported operator: {op!r}")

    ops = list(operators)
    vals = list(operands)

    # Each operand k is followed by operator k (if any). Each parse function
    # takes the index of the operand where it starts and returns the value
    # together with the index of the operand where the next unparsed
    # operator (if any) sits.

    def parse_power(idx):
        # "**" is right-associative: a ** b ** c == a ** (b ** c)
        base = vals[idx]
        if idx < len(ops) and ops[idx] == "**":
            exponent, nxt = parse_power(idx + 1)
            return base ** exponent, nxt
        return base, idx

    def parse_term(idx):
        # "*" and "//" are left-associative and bind looser than "**"
        value, idx = parse_power(idx)
        while idx < len(ops) and ops[idx] in ("*", "//"):
            op = ops[idx]
            rhs, idx = parse_power(idx + 1)
            if op == "*":
                value = value * rhs
            else:
                value = value // rhs
        return value, idx

    def parse_expr(idx):
        # "+" and "-" are left-associative and bind loosest
        value, idx = parse_term(idx)
        while idx < len(ops) and ops[idx] in ("+", "-"):
            op = ops[idx]
            rhs, idx = parse_term(idx + 1)
            if op == "+":
                value = value + rhs
            else:
                value = value - rhs
        return value, idx

    result, _ = parse_expr(0)
    return result

