    for op, operand in zip(operators, operands[1:]):
        while pending_ops and (
            precedence[pending_ops[-1]] > precedence[op]
            or (
                precedence[pending_ops[-1]] == precedence[op]
                and op not in right_associative
            )
        ):
            apply_top()
        pending_ops.append(op)
        values.append(operand)

    while pending_ops:
        apply_top()

    return values[0]
