    result = []
    # Stack of iterators; each level of nesting pushes one iterator,
    # so depth is limited by memory rather than the recursion limit.
    stack = [iter(nested)]
    while stack:
        try:
            item = next(stack[-1])
        except StopIteration:
            stack.pop()
            continue
        if isinstance(item, (list, tuple)):
            stack.append(iter(item))
        else:
            result.append(item)
