def parse_kv(line: str) -> dict:
    result = {}
    n = len(line)
    i = 0
    while i < n:
        # Parse the key: everything up to '=' or ';'
        start = i
        while i < n and line[i] not in "=;":
            i += 1
        key = line[start:i].strip()

        # Bare key (or empty item)
        if i >= n or line[i] == ";":
            if key:
                result[key] = True
            i += 1
            continue

        # key=value form
        if not key:
            raise ValueError("empty key in item")
        i += 1  # skip '='
        while i < n and line[i].isspace():
            i += 1

        if i < n and line[i] == '"':
            # Quoted value
            i += 1
            chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == "\\" and i + 1 < n and line[i + 1] in '"\\':
                    chars.append(line[i + 1])
                    i += 2
                elif c == '"':
                    closed = True
                    i += 1
                    break
                else:
                    chars.append(c)
                    i += 1
            if not closed:
                raise ValueError("unterminated quoted value")
            # Only whitespace may follow the closing quote before ';' or end
            while i < n and line[i] != ";":
                if not line[i].isspace():
                    raise ValueError("unexpected character after closing quote")
                i += 1
            value = "".join(chars)
            if i < n:
                i += 1  # skip ';'
        else:
            # Unquoted value
            start = i
            while i < n and line[i] != ";":
                i += 1
            value = line[start:i].strip()
            i += 1  # skip ';' (harmless at end of string)

        result[key] = value

    return result

