def parse_kv(line: str) -> dict:
    result = {}
    n = len(line)
    i = 0

    while True:
        # Read the key: everything up to '=' or ';'.
        start = i
        while i < n and line[i] not in "=;":
            i += 1
        key = line[start:i].strip()

        if i < n and line[i] == "=":
            i += 1  # consume '='
            # Skip whitespace before a possible opening quote.
            j = i
            while j < n and line[j].isspace():
                j += 1

            if j < n and line[j] == '"':
                # Quoted value: ';' is literal, \" and \\ are escapes.
                j += 1
                chars = []
                closed = False
                while j < n:
                    c = line[j]
                    if c == "\\" and j + 1 < n and line[j + 1] in '"\\':
                        chars.append(line[j + 1])
                        j += 2
                    elif c == '"':
                        closed = True
                        j += 1
                        break
                    else:
                        chars.append(c)
                        j += 1
                if not closed:
                    raise ValueError("unterminated quoted value")

                # Only whitespace may follow the closing quote before ';' or end.
                while j < n and line[j] != ";":
                    if not line[j].isspace():
                        raise ValueError("unexpected characters after quoted value")
                    j += 1

                value = "".join(chars)
                i = j
            else:
                # Unquoted value: runs to the next ';', stripped of whitespace.
                vstart = i
                while i < n and line[i] != ";":
                    i += 1
                value = line[vstart:i].strip()

            result[key] = value
        else:
            # Bare key (or empty item).
            if key:
                result[key] = True

        # Move past the item terminator, or finish.
        if i >= n:
            break
        i += 1  # skip ';'

    return result
