from collections import OrderedDict


class TTLCache:
    """LRU cache whose entries expire after a fixed time-to-live.

    Time is supplied explicitly by the caller as `now`; the cache never
    reads a clock. An entry written at time t expires at t + ttl and is
    considered expired whenever now >= t + ttl.
    """

    def __init__(self, capacity: int, ttl: float):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
