def _tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
        elif "0" <= c <= "9":
            j = i
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(("NUM", int(expr[i:j])))
            i = j
        elif c in "+-*/%^()":
            tokens.append(("OP", c))
            i += 1
        else:
            raise SyntaxError(f"unexpected character {c!r} at position {i}")
    return tokens


def _trunc_div(a: int, b: int) -> int:
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def _trunc_mod(a: int, b: int) -> int:
    return a - b * _trunc_div(a, b)


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def _peek_op(self):
        if self.pos < len(self.tokens):
            kind, value = self.tokens[self.pos]
            if kind == "OP":
                return value
        return None

    def _advance(self):
        if self.pos >= len(self.tokens):
            raise SyntaxError("unexpected end of expression")
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def parse(self) -> int:
        if not self.tokens:
            raise SyntaxError("empty expression")
        value = self._parse_expr()
        if self.pos != len(self.tokens):
            raise SyntaxError("unexpected trailing tokens")
        return value

    # expr := term (('+' | '-') term)*
    def _parse_expr(self) -> int:
        value = self._parse_term()
        while self._peek_op() in ("+", "-"):
            op = self._advance()[1]
            rhs = self._parse_term()
            value = value + rhs if op == "+" else value - rhs
        return value

    # term := unary (('*' | '/' | '%') unary)*
    def _parse_term(self) -> int:
        value = self._parse_unary()
        while self._peek_op() in ("*", "/", "%"):
            op = self._advance()[1]
            rhs = self._parse_unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = _trunc_div(value, rhs)
            else:
                value = _trunc_mod(value, rhs)
        return value

    # unary := '-' unary | power
    def _parse_unary(self) -> int:
        if self._peek_op() == "-":
            self._advance()
            return -self._parse_unary()
        return self._parse_power()

    # power := primary ('^' exponent)?
    def _parse_power(self) -> int:
        base = self._parse_primary()
        if self._peek_op() == "^":
            self._advance()
            exp = self._parse_exponent()
            if exp < 0:
                raise ValueError("negative exponent is not supported")
            return base ** exp
        return base

    # exponent := '-' exponent | power   (right-associative, may carry unary minus)
    def _parse_exponent(self) -> int:
        if self._peek_op() == "-":
            self._advance()
            return -self._parse_exponent()
        return self._parse_power()

    # primary := NUMBER | '(' expr ')'
    def _parse_primary(self) -> int:
        if self.pos >= len(self.tokens):
            raise SyntaxError("unexpected end of expression")
        kind, value = self._advance()
        if kind == "NUM":
            return value
        if value == "(":
            inner = self._parse_expr()
            if self._peek_op() != ")":
                raise SyntaxError("expected ')'")
            self._advance()
            return inner
        raise SyntaxError(f"unexpected token {value!r}")


def evaluate(expr: str) -> int:
    tokens = _tokenize(expr)
    return _Parser(tokens).parse()

