        return tokens[pos][0] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_expr():
        # expr := term (('+' | '-') term)*
        node = parse_term()
        while peek() in ('+', '-'):
            op = advance()[0]
            rhs = parse_term()
            node = ('bin', op, node, rhs)
        return node

    def parse_term():
        # term := unary (('*' | '/' | '%') unary)*
        node = parse_unary()
        while peek() in ('*', '/', '%'):
            op = advance()[0]
            rhs = parse_unary()
            node = ('bin', op, node, rhs)
        return node

    def parse_unary():
        # unary := '-' unary | power
        if peek() == '-':
            advance()
            return ('neg', parse_unary())
        return parse_power()

    def parse_power():
        # power := atom ('^' exponent)?     (right-associative via exponent -> power)
        base = parse_atom()
        if peek() == '^':
            advance()
            exp = parse_exponent()
            return ('bin', '^', base, exp)
        return base

    def parse_exponent():
        # exponent := '-' exponent | power
        if peek() == '-':
            advance()
            return ('neg', parse_exponent())
        return parse_power()

    def parse_atom():
        # atom := NUMBER | '(' expr ')'
        kind = peek()
        if kind is None:
            raise SyntaxError("unexpected end of expression")
        if kind == 'num':
            value = advance()[1]
            return ('num', value)
        if kind == '(':
            advance()
            node = parse_expr()
            if peek() != ')':
                raise SyntaxError("expected ')'")
            advance()
            return node
        raise SyntaxError(f"unexpected token {kind!r}")

    if not tokens:
        raise SyntaxError("empty expression")

    tree = parse_expr()
    if pos != len(tokens):
        raise SyntaxError(f"unexpected token {tokens[pos][0]!r}")

    # ---- Evaluator ----
    def trunc_divmod(a, b):
        # Quotient truncates toward zero; remainder takes the sign of the dividend.
        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        r = a - b * q
        return q, r

    def ev(node):
        kind = node[0]
        if kind == 'num':
            return node[1]
        if kind == 'neg':
            return -ev(node[1])
        # binary operation
        _, op, lhs, rhs = node
        a = ev(lhs)
        b = ev(rhs)
        if op == '+':
            return a + b
        if op == '-':
            return a - b
        if op == '*':
            return a * b
        if op == '/':
            return trunc_divmod(a, b)[0]
        if op == '%':
            return trunc_divmod(a, b)[1]
        if op == '^':
            if b < 0:
                raise ValueError("negative exponent")
            return a ** b
        raise SyntaxError(f"unknown operator {op!r}")

    return ev(tree)
