class _Parser:
    # Grammar (lowest to highest precedence):
    #   expr    := term (('+' | '-') term)*
    #   term    := unary (('*' | '/' | '%') unary)*
    #   unary   := '-' unary | power
    #   power   := primary ('^' exponent)?      (right-associative via power)
    #   exponent:= '-' exponent | power
    #   primary := NUM | '(' expr ')'

    def __init__(self, tokens):
        self.toks = tokens
        self.pos = 0

    def _peek_kind(self):
        if self.pos < len(self.toks):
            return self.toks[self.pos][0]
        return None

    def _advance(self):
        tok = self.toks[self.pos]
        self.pos += 1
        return tok

    def parse(self):
        if not self.toks:
            raise SyntaxError("empty expression")
        node = self._expr()
        if self.pos != len(self.toks):
            raise SyntaxError("unexpected trailing tokens")
        return node

    def _expr(self):
        node = self._term()
        while self._peek_kind() in ("+", "-"):
            op = self._advance()[0]
            node = ("bin", op, node, self._term())
        return node

    def _term(self):
        node = self._unary()
        while self._peek_kind() in ("*", "/", "%"):
            op = self._advance()[0]
            node = ("bin", op, node, self._unary())
        return node

    def _unary(self):
        if self._peek_kind() == "-":
            self._advance()
            return ("neg", self._unary())
        return self._power()

    def _power(self):
        base = self._primary()
        if self._peek_kind() == "^":
            self._advance()
            return ("pow", base, self._exponent())
        return base

    def _exponent(self):
        if self._peek_kind() == "-":
            self._advance()
            return ("neg", self._exponent())
        return self._power()

    def _primary(self):
        kind = self._peek_kind()
        if kind == "num":
            return ("num", self._advance()[1])
        if kind == "(":
            self._advance()
            node = self._expr()
            if self._peek_kind() != ")":
                raise SyntaxError("expected ')'")
            self._advance()
            return node
        raise SyntaxError("expected number or '('")


def _eval_tree(node):
    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "neg":
        return -_eval_tree(node[1])
    if kind == "pow":
        base = _eval_tree(node[1])
        exp = _eval_tree(node[2])
        if exp < 0:
            raise ValueError("negative exponent")
        return base ** exp
    if kind == "bin":
        op = node[1]
        left = _eval_tree(node[2])
        right = _eval_tree(node[3])
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if right == 0:
            raise ZeroDivisionError("division or remainder by zero")
        quotient = abs(left) // abs(right)
        if (left < 0) != (right < 0):
            quotient = -quotient
        if op == "/":
            return quotient
        return left - right * quotient  # op == "%"
    raise SyntaxError("invalid expression tree")

