class VendingMachine:
    VALID_COINS = (25, 10, 5)

    def __init__(self, prices: dict[str, int], coins: dict[int, int]):
        self._prices = dict(prices)
        self._inventory = {int(d): int(c) for d, c in coins.items()}
        self._balance = 0
        self._pending = []  # coins inserted since last successful select/cancel

    def insert(self, coin: int) -> bool:
        if coin not in self.VALID_COINS:
            return False
        self._balance += coin
        self._inventory[coin] = self._inventory.get(coin, 0) + 1
        self._pending.append(coin)
        return True

    def balance(self) -> int:
        return self._balance

    def _available(self, denom: int) -> int:
        return self._inventory.get(denom, 0)

    def _make_change(self, amount: int):
        """Return (total_coins, {denom: count}) using the fewest coins, or None."""
        best = None
        for q in range(min(self._available(25), amount // 25), -1, -1):
            rem_q = amount - 25 * q
            for t in range(min(self._available(10), rem_q // 10), -1, -1):
                rem = rem_q - 10 * t
                if rem % 5 != 0:
                    continue
                n = rem // 5
                if n > self._available(5):
                    continue
                total = q + t + n
                if best is None or total < best[0]:
                    best = (total, {25: q, 10: t, 5: n})
        return best

    def select(self, item: str):
        if item not in self._prices:
            return "UNKNOWN"
        price = self._prices[item]
        if self._balance < price:
            return "INSUFFICIENT"
        change_owed = self._balance - price
        result = self._make_change(change_owed)
        if result is None:
            return "NO_CHANGE"
        _, counts = result
        for denom, count in counts.items():
            self._inventory[denom] = self._inventory.get(denom, 0) - count
        change_coins = sorted(
            (d for d, c in counts.items() for _ in range(c)), reverse=True
        )
        self._balance = 0
        self._pending = []
        return change_coins

    def cancel(self) -> list[int]:
        returned = sorted(self._pending, reverse=True)
        for coin in self._pending:
            self._inventory[coin] = self._inventory.get(coin, 0) - 1
        self._balance = 0
        self._pending = []
        return returned

