class VendingMachine:
    ACCEPTED_COINS = (5, 10, 25)
    _INF = float("inf")

    def __init__(self, prices: dict[str, int], coins: dict[int, int]):
        self._prices = dict(prices)
        self._inventory: dict[int, int] = {
            d: c for d, c in coins.items() if c > 0
        }
        self._balance = 0
        self._inserted: list[int] = []

    def insert(self, coin: int) -> bool:
        if coin not in self.ACCEPTED_COINS:
            return False
        self._balance += coin
        self._inserted.append(coin)
        self._inventory[coin] = self._inventory.get(coin, 0) + 1
        return True

    def balance(self) -> int:
        return self._balance

    def select(self, item: str) -> list[int] | str:
        if item not in self._prices:
            return "UNKNOWN"
        price = self._prices[item]
        if self._balance < price:
            return "INSUFFICIENT"

        change_amount = self._balance - price
        change = self._make_change(change_amount)
        if change is None:
            return "NO_CHANGE"

        for coin in change:
            self._remove_coin(coin)

        self._balance = 0
        self._inserted = []
        return sorted(change, reverse=True)

    def cancel(self) -> list[int]:
        returned = sorted(self._inserted, reverse=True)
        for coin in self._inserted:
            self._remove_coin(coin)
        self._inserted = []
        self._balance = 0
        return returned

    def _remove_coin(self, coin: int) -> None:
        self._inventory[coin] -= 1
        if self._inventory[coin] <= 0:
            del self._inventory[coin]

    def _make_change(self, amount: int) -> Optional[list[int]]:
        """Return a minimum-coin combination summing to amount using the
        current inventory, or None if no such combination exists."""
        if amount == 0:
            return []

        denoms = sorted(d for d, c in self._inventory.items() if c > 0 and d > 0)

        # Bounded coin-change DP: for each denomination, choose how many
        # coins (0..available) to use, minimizing total coin count.
        prev = [self._INF] * (amount + 1)
        prev[0] = 0
        choices: list[list[int]] = []

        for d in denoms:
            available = self._inventory[d]
            cur = [self._INF] * (amount + 1)
            choice = [0] * (amount + 1)
            for v in range(amount + 1):
                max_j = min(available, v // d)
                for j in range(max_j + 1):
                    base = prev[v - j * d]
                    if base == self._INF:
                        continue
                    cand = base + j
                    if cand < cur[v]:
                        cur[v] = cand
                        choice[v] = j
            choices.append(choice)
            prev = cur

        if prev[amount] == self._INF:
            return None

        # Reconstruct the chosen coins.
        result: list[int] = []
        v = amount
        for i in range(len(denoms) - 1, -1, -1):
            d = denoms[i]
            j = choices[i][v]
            result.extend([d] * j)
            v -= j * d
        return result

