    def __init__(self, prices: dict[str, int], coins: dict[int, int]):
        self._prices = dict(prices)
        self._inventory = defaultdict(int)
        for denom, count in coins.items():
            if count > 0:
                self._inventory[denom] += count
        self._pending = []  # coins inserted since last successful select/cancel

    def insert(self, coin: int) -> bool:
        if coin not in self.ACCEPTED:
            return False
        self._pending.append(coin)
        self._inventory[coin] += 1
        return True

    def balance(self) -> int:
        return sum(self._pending)

    def select(self, item: str) -> list[int] | str:
        if item not in self._prices:
            return "UNKNOWN"
        price = self._prices[item]
        bal = self.balance()
        if bal < price:
            return "INSUFFICIENT"
        change_due = bal - price
        change = self._make_change(change_due)
        if change is None:
            return "NO_CHANGE"
        for coin in change:
            self._inventory[coin] -= 1
        self._pending = []
        return sorted(change, reverse=True)

    def cancel(self) -> list[int]:
        returned = sorted(self._pending, reverse=True)
        for coin in self._pending:
            self._inventory[coin] -= 1
        self._pending = []
        return returned

    def _make_change(self, amount: int) -> list[int] | None:
        """Return a minimum-coin combination summing to amount using the
        current inventory (bounded counts), or None if impossible."""
        if amount == 0:
            return []

        # Expand inventory into individual coin instances.
        items = []
        for denom in sorted(self._inventory, reverse=True):
            count = self._inventory[denom]
            if denom > 0 and count > 0:
                items.extend([denom] * count)

        INF = float("inf")
        dp = [INF] * (amount + 1)
        dp[0] = 0
        take = [[False] * (amount + 1) for _ in items]

        # 0/1 knapsack over individual coins, minimizing coin count.
        for i, d in enumerate(items):
            if d > amount:
                continue
            for s in range(amount, d - 1, -1):
                if dp[s - d] + 1 < dp[s]:
                    dp[s] = dp[s - d] + 1
                    take[i][s] = True

        if dp[amount] == INF:
            return None

        # Reconstruct the chosen coins.
        result = []
        s = amount
        for i in range(len(items) - 1, -1, -1):
            if s == 0:
                break
            if take[i][s]:
                result.append(items[i])
                s -= items[i]
        return result
