from typing import Dict, List, Optional, Union


class VendingMachine:
    ACCEPTED_COINS = (5, 10, 25)

    def __init__(self, prices: Dict[str, int], coins: Dict[int, int]):
        self.prices: Dict[str, int] = dict(prices)
        self.coins: Dict[int, int] = {d: c for d, c in coins.items() if c > 0}
        self._balance: int = 0
        self._transaction: List[int] = []

    def insert(self, coin: int) -> bool:
        if coin not in self.ACCEPTED_COINS:
            return False
        self._balance += coin
        self.coins[coin] = self.coins.get(coin, 0) + 1
        self._transaction.append(coin)
        return True

    def balance(self) -> int:
        return self._balance

    def select(self, item: str) -> Union[List[int], str]:
        if item not in self.prices:
            return "UNKNOWN"
        price = self.prices[item]
        if self._balance < price:
            return "INSUFFICIENT"

        change_amount = self._balance - price
        plan = self._plan_change(change_amount)
        if plan is None:
            return "NO_CHANGE"

        for denom, count in plan.items():
            self._remove_coins(denom, count)

        returned = sorted(
            [d for d, cnt in plan.items() for _ in range(cnt)], reverse=True
        )
        self._balance = 0
        self._transaction = []
        return returned

    def cancel(self) -> List[int]:
        returned = sorted(self._transaction, reverse=True)
        for coin in self._transaction:
            self._remove_coins(coin, 1)
        self._transaction = []
        self._balance = 0
        return returned

    def _remove_coins(self, denom: int, count: int) -> None:
        remaining = self.coins.get(denom, 0) - count
        if remaining > 0:
            self.coins[denom] = remaining
        else:
            self.coins.pop(denom, None)

    def _plan_change(self, amount: int) -> Optional[Dict[int, int]]:
        """Return a dict denomination -> count using the fewest coins that
        exactly makes `amount` from the current inventory, or None if impossible."""
        if amount == 0:
            return {}

        dens = sorted(
            (d for d, c in self.coins.items() if d > 0 and c > 0), reverse=True
        )
        n = len(dens)
        INF = float("inf")
        memo: Dict[tuple, float] = {}

        def best(i: int, rem: int):
            # Minimum number of coins from dens[i:] summing exactly to rem.
            if rem == 0:
                return 0
            if i == n:
                return INF
            key = (i, rem)
            if key in memo:
                return memo[key]
            d = dens[i]
            limit = min(self.coins[d], rem // d)
            result = INF
            for k in range(limit + 1):
                sub = best(i + 1, rem - k * d)
                if sub + k < result:
                    result = sub + k
            memo[key] = result
            return result

        target = best(0, amount)
        if target == INF:
            return None

        plan: Dict[int, int] = {}
        rem = amount
        for i in range(n):
            if rem == 0:
                break
            d = dens[i]
            limit = min(self.coins[d], rem // d)
            for k in range(limit + 1):
                if k + best(i + 1, rem - k * d) == best(i, rem):
                    if k > 0:
                        plan[d] = k
                    rem -= k * d
                    break
        return plan

