from typing import Any, Callable, Optional, Tuple

Result = Optional[Tuple[Any, int]]
Parser = Callable[[str, int], Result]


class ParseError(Exception):
    def __init__(self, message: str, pos: int):
        super().__init__(message)
        self.pos = pos


def char(c: str) -> Parser:
    def p(s: str, i: int) -> Result:
        if i < len(s) and s[i] == c:
            return (c, i + 1)
        return None
    return p


def string(lit: str) -> Parser:
    def p(s: str, i: int) -> Result:
        if s.startswith(lit, i):
            return (lit, i + len(lit))
        return None
    return p


def satisfy(pred: Callable[[str], bool]) -> Parser:
    def p(s: str, i: int) -> Result:
        if i < len(s) and pred(s[i]):
            return (s[i], i + 1)
        return None
    return p


def seq(*ps: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        values = []
        j = i
        for q in ps:
            r = q(s, j)
            if r is None:
                return None
            v, j = r
            values.append(v)
        return (values, j)
    return p


def alt(*ps: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        for q in ps:
            r = q(s, i)
            if r is not None:
                return r
        return None
    return p


def many(q: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        values = []
        j = i
        while True:
            r = q(s, j)
            if r is None:
                break
            v, k = r
            if k == j:
                # Non-consuming success: discard and stop to guarantee termination.
                break
            values.append(v)
            j = k
        return (values, j)
    return p


def sep_by(q: Parser, sep: Parser) -> Parser:
    def p(s: str, i: int) -> Result:
        first = q(s, i)
        if first is None:
            return ([], i)
        v, j = first
        values = [v]
        while True:
            sr = sep(s, j)
            if sr is None:
                break
            _, after_sep = sr
            r = q(s, after_sep)
            if r is None:
                # Trailing separator not followed by an item is not consumed.
                break
            v, k = r
            if k == j:
                break
            values.append(v)
            j = k
        return (values, j)
    return p


def map_(q: Parser, f: Callable[[Any], Any]) -> Parser:
    def p(s: str, i: int) -> Result:
        r = q(s, i)
        if r is None:
            return None
        v, j = r
        return (f(v), j)
    return p


def parse(q: Parser, s: str) -> Any:
    r = q(s, 0)
    if r is None:
        raise ParseError("parse failed", 0)
    value, j = r
    if j < len(s):
        raise ParseError(f"unconsumed input at position {j}", j)
    return value

