import bisect


class Scheduler:
    """Books a single room using half-open integer intervals [start, end)."""

    def __init__(self) -> None:
        # Kept sorted by start. Bookings never overlap, so starts are unique.
        self._bookings: list[tuple[int, int]] = []

    def book(self, start: int, end: int) -> bool:
        if start >= end:
            raise ValueError("start must be less than end")

        idx = bisect.bisect_left(self._bookings, (start, end))

        # The previous booking overlaps if it ends after our start.
        if idx > 0:
            _, prev_end = self._bookings[idx - 1]
            if prev_end > start:
                return False

        # The next booking overlaps if it starts before our end.
        if idx < len(self._bookings):
            next_start, _ = self._bookings[idx]
            if next_start < end:
                return False

        self._bookings.insert(idx, (start, end))
        return True

    def cancel(self, start: int, end: int) -> bool:
        idx = bisect.bisect_left(self._bookings, (start, end))
        if idx < len(self._bookings) and self._bookings[idx] == (start, end):
            del self._bookings[idx]
            return True
        return False

    def bookings(self) -> list[tuple[int, int]]:
        return list(self._bookings)

    def free_slots(self, lo: int, hi: int, min_len: int = 1) -> list[tuple[int, int]]:
        if lo >= hi:
            return []

        result: list[tuple[int, int]] = []
        cursor = lo

        for b_start, b_end in self._bookings:
            if b_end <= lo or b_start >= hi:
                continue
            s = max(b_start, lo)
            e = min(b_end, hi)
            if s > cursor:
                gap = (cursor, s)
                if gap[1] - gap[0] >= min_len:
                    result.append(gap)
            cursor = max(cursor, e)

        if cursor < hi:
            gap = (cursor, hi)
            if gap[1] - gap[0] >= min_len:
                result.append(gap)

        return result

