class Scheduler:
    """Books a single room using half-open integer intervals [start, end)."""

    def __init__(self) -> None:
        # Sorted list of non-overlapping (start, end) tuples.
        # Because intervals do not overlap, sorting by start also sorts by end.
        self._bookings: list[tuple[int, int]] = []

    def book(self, start: int, end: int) -> bool:
        if start >= end:
            raise ValueError("start must be less than end")

        i = bisect.bisect_left(self._bookings, (start, end))

        # Only the immediate neighbours can overlap the new interval.
        if i > 0 and self._bookings[i - 1][1] > start:
            return False
        if i < len(self._bookings) and self._bookings[i][0] < end:
            return False

        self._bookings.insert(i, (start, end))
        return True

    def cancel(self, start: int, end: int) -> bool:
        i = bisect.bisect_left(self._bookings, (start, end))
        if i < len(self._bookings) and self._bookings[i] == (start, end):
            del self._bookings[i]
            return True
        return False

    def bookings(self) -> list[tuple[int, int]]:
        return list(self._bookings)

    def free_slots(self, lo: int, hi: int, min_len: int = 1) -> list[tuple[int, int]]:
        if lo >= hi:
            return []

        result: list[tuple[int, int]] = []
        cursor = lo

        for s, e in self._bookings:
            # Skip bookings entirely outside the window.
            if e <= lo or s >= hi:
                continue

            # Clip the booking to the window.
            cs = max(s, lo)
            ce = min(e, hi)

            if cs > cursor and cs - cursor >= min_len:
                result.append((cursor, cs))
            cursor = max(cursor, ce)

        if cursor < hi and hi - cursor >= min_len:
            result.append((cursor, hi))

