def color_graph(nodes, edges, k, precolored=None):
    """Return a proper k-coloring of the graph as a dict, or None if none exists.

    nodes:      iterable of hashable node names (endpoints of edges are also nodes)
    edges:      list of (u, v) pairs describing an undirected graph
    k:          number of available colors, labeled 0 .. k-1
    precolored: optional dict mapping some nodes to fixed colors that must be kept
    """
    # Collect every node, preserving first-seen order.
    all_nodes = []
    seen = set()

    def add_node(n):
        if n not in seen:
            seen.add(n)
            all_nodes.append(n)

    for n in nodes:
        add_node(n)

    adj = {}
    edge_list = []
    for e in edges:
        u, v = e
        if u == v:
            return None  # self-loop can never be properly colored
        add_node(u)
        add_node(v)
        edge_list.append((u, v))
    for n in all_nodes:
        adj[n] = set()
    for u, v in edge_list:
        adj[u].add(v)
        adj[v].add(u)

    precolored = dict(precolored) if precolored else {}
    for n in precolored:
        add_node(n)
        adj.setdefault(n, set())

    if not all_nodes:
        return {}
    if not isinstance(k, int) or k <= 0:
        return None

