def color_graph(nodes, edges, k, precolored=None) -> dict | None:
    node_set = set(nodes)
    edge_pairs = []
    for u, v in edges:
        if u == v:
            return None  # self-loop can never be properly colored
        node_set.add(u)
        node_set.add(v)
        edge_pairs.append((u, v))

    precolored = dict(precolored or {})
    for n, c in precolored.items():
        if not isinstance(c, int) or not (0 <= c < k):
            return None
        node_set.add(n)

    adj = {n: set() for n in node_set}
    for u, v in edge_pairs:
        adj[u].add(v)
        adj[v].add(u)

    assignment = {}
    for n, c in precolored.items():
        assignment[n] = c
    # Precolorings that conflict with each other are invalid.
    for n, c in precolored.items():
        for m in adj[n]:
            if m in precolored and precolored[m] == c:
                return None

    def available(n):
        used = {assignment[m] for m in adj[n] if m in assignment}
        return [c for c in range(k) if c not in used]

    def solve():
        uncolored = [n for n in node_set if n not in assignment]
        if not uncolored:
            return True
        # Choose the uncolored node with the fewest legal colors.
        best = None
        best_opts = None
        for n in uncolored:
            opts = available(n)
            if not opts:
                return False
            if best_opts is None or len(opts) < len(best_opts):
                best, best_opts = n, opts
        for c in best_opts:
            assignment[best] = c
            if solve():
                return True
            del assignment[best]
        return False

    if not solve():
        return None
    return {n: assignment[n] for n in node_set}

