def color_graph(nodes, edges, k, precolored=None):
    # Build the undirected adjacency structure.
    adj = {}

    def add_node(n):
        if n not in adj:
            adj[n] = set()

    for n in nodes:
        add_node(n)

    for e in edges:
        u, v = e
        if u == v:
            return None  # self-loop can never be properly colored
        add_node(u)
        add_node(v)
        adj[u].add(v)
        adj[v].add(u)

    if precolored is None:
        precolored = {}
    else:
        precolored = dict(precolored)

    for n in precolored:
        add_node(n)

    # Trivial cases.
    if not adj:
        return {}
    if k is None or k <= 0:
        return None

    # Validate precolorings: colors must be in range and must not conflict.
    for n, c in precolored.items():
        if not isinstance(c, int) or isinstance(c, bool) or not (0 <= c < k):
            return None
    for n, c in precolored.items():
        for m in adj[n]:
            if m in precolored and precolored[m] == c:
                return None

    colors = dict(precolored)

    def available(n):
        used = {colors[m] for m in adj[n] if m in colors}
        return [c for c in range(k) if c not in used]

    def solve():
        uncolored = [n for n in adj if n not in colors]
        if not uncolored:
            return True

        # Minimum-remaining-values heuristic: pick the most constrained node.
        best = None
        best_opts = None
        for n in uncolored:
            opts = available(n)
            if not opts:
                return False
            if best_opts is None or len(opts) < len(best_opts):
                best, best_opts = n, opts
                if len(opts) == 1:
                    break

        # Symmetry breaking: colors not used by any node so far are
        # interchangeable, so only try the lowest such color.
        used_colors = set(colors.values())
        candidates = []
        fresh_tried = False
        for c in best_opts:
            if c in used_colors:
                candidates.append(c)
            elif not fresh_tried:
                candidates.append(c)
                fresh_tried = True

        for c in candidates:
            colors[best] = c
            if solve():
                return True
            del colors[best]
        return False

    if solve():
        return {n: colors[n] for n in adj}
    return None

