def wrap_text(text: str, width: int) -> str:
    if width < 1:
        raise ValueError("width must be at least 1")

    # Group consecutive non-blank lines into paragraphs.
    paragraphs = []
    current = []
    for line in text.splitlines():
        if line.strip() == "":
            if current:
                paragraphs.append(current)
                current = []
        else:
            current.append(line)
    if current:
        paragraphs.append(current)

    wrapped_paragraphs = []
    for group in paragraphs:
        words = " ".join(group).split()

        # Split over-long words into width-sized pieces, each treated as a word.
        tokens = []
        for word in words:
            for i in range(0, len(word), width):
                tokens.append(word[i:i + width])

        # Greedy line filling.
        lines = []
        cur = ""
        for token in tokens:
            if not cur:
                cur = token
            elif len(cur) + 1 + len(token) <= width:
                cur += " " + token
            else:
                lines.append(cur)
                cur = token
        if cur:
            lines.append(cur)

        wrapped_paragraphs.append("\n".join(lines))

    return "\n\n".join(wrapped_paragraphs)

