import heapq


class CycleError(Exception):
    """Raised when the dependency graph contains a cycle.

    The `cycle` attribute is a list [p0, p1, ..., pn] with p0 == pn and n >= 1,
    where each p_i directly depends on p_(i+1).
    """

    def __init__(self, cycle):
        self.cycle = cycle
        super().__init__("dependency cycle: " + " -> ".join(cycle))


def _find_cycle(needs, remaining):
    """Extract one cycle from the subgraph of packages that were never placed."""
    unplaced = [n for n in needs if remaining[n] > 0]
    cur = min(unplaced)
    path = []
    position = {}
    while cur not in position:
        position[cur] = len(path)
        path.append(cur)
        # Every unplaced package has at least one unplaced dependency.
        cur = min(d for d in needs[cur] if remaining[d] > 0)
    return path[position[cur]:] + [cur]


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Every package mentioned anywhere is a package.
    nodes = set(deps)
    for dep_list in deps.values():
        nodes.update(dep_list)

    # Distinct direct dependencies per package (duplicates are harmless).
    needs = {n: set() for n in nodes}
    for pkg, dep_list in deps.items():
        needs[pkg].update(dep_list)

    # Reverse edges: for each package, who depends on it.
    dependents = {n: [] for n in nodes}
    for pkg, dep_set in needs.items():
        for d in dep_set:
            dependents[d].append(pkg)

    # Number of dependencies not yet placed.
    remaining = {n: len(needs[n]) for n in nodes}

    # Min-heap of packages whose dependencies are all placed gives the
    # lexicographically smallest valid order.
    ready = [n for n in nodes if remaining[n] == 0]
    heapq.heapify(ready)

    order = []
    while ready:
        n = heapq.heappop(ready)
        order.append(n)
        for m in dependents[n]:
            remaining[m] -= 1
            if remaining[m] == 0:
                heapq.heappush(ready, m)

    if len(order) != len(nodes):
        raise CycleError(_find_cycle(needs, remaining))

    return order

