import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Build the full set of packages and their unique direct dependencies.
    graph: dict[str, set[str]] = {}
    for pkg, dep_list in deps.items():
        graph.setdefault(pkg, set())
        for d in dep_list:
            graph[pkg].add(d)
            graph.setdefault(d, set())

    # Reverse edges: dependents[d] = packages that directly depend on d.
    dependents: dict[str, list[str]] = {n: [] for n in graph}
    indegree: dict[str, int] = {}
    for n, ds in graph.items():
        indegree[n] = len(ds)
        for d in ds:
            dependents[d].append(n)

    # Kahn's algorithm with a min-heap gives the lexicographically smallest order.
    heap = [n for n in graph if indegree[n] == 0]
    heapq.heapify(heap)
    result: list[str] = []
    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for m in dependents[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    if len(result) == len(graph):
        return result

    # Every unplaced package has at least one unplaced dependency, so walking
    # along unplaced dependencies must eventually revisit a package: that is a cycle.
    remaining = set(graph) - set(result)
    cur = min(remaining)
    path: list[str] = []
    position: dict[str, int] = {}
    while cur not in position:
        position[cur] = len(path)
        path.append(cur)
        cur = min(d for d in graph[cur] if d in remaining)
    cycle = path[position[cur]:] + [cur]
    raise CycleError(cycle)

