import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        self.cycle = list(cycle)
        super().__init__("dependency cycle: " + " -> ".join(self.cycle))


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Build the full graph: every package (including dependency-only ones) maps
    # to the set of packages it directly depends on.
    graph: dict[str, set[str]] = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, set()).update(ds)
        for d in ds:
            graph.setdefault(d, set())

    # Cycle detection with an iterative DFS (avoids recursion limits).
    # state: 0 = unvisited, 1 = on the current path, 2 = finished.
    state = {n: 0 for n in graph}
    for start in sorted(graph):
        if state[start]:
            continue
        state[start] = 1
        path = [start]
        iters = [iter(sorted(graph[start]))]
        while iters:
            nxt = next(iters[-1], None)
            if nxt is None:
                # No more dependencies to explore for the top of the path.
                state[path.pop()] = 2
                iters.pop()
                continue
            if state[nxt] == 1:
                # Back edge: path[i] ... path[-1] -> nxt forms a cycle.
                i = path.index(nxt)
                raise CycleError(path[i:] + [nxt])
            if state[nxt] == 0:
                state[nxt] = 1
                path.append(nxt)
                iters.append(iter(sorted(graph[nxt])))

    # Kahn's algorithm with a min-heap for the lexicographically smallest order.
    indegree = {n: len(graph[n]) for n in graph}
    dependents: dict[str, list[str]] = {n: [] for n in graph}
    for n, ds in graph.items():
        for d in ds:
            dependents[d].append(n)

    heap = [n for n, k in indegree.items() if k == 0]
    heapq.heapify(heap)

    result: list[str] = []
    while heap:
        n = heapq.heappop(heap)
        result.append(n)
        for m in dependents[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    return result

