def _find_cycle(graph):
    """Return a cycle [p0, ..., pn] with p0 == pn, where each p_i depends on p_(i+1)."""
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {n: WHITE for n in graph}

    for start in sorted(graph):
        if color[start] != WHITE:
            continue
        path = [start]
        idx_stack = [0]
        color[start] = GRAY
        while path:
            node = path[-1]
            i = idx_stack[-1]
            nbrs = graph[node]
            if i < len(nbrs):
                idx_stack[-1] += 1
                nxt = nbrs[i]
                if color[nxt] == WHITE:
                    color[nxt] = GRAY
                    path.append(nxt)
                    idx_stack.append(0)
                elif color[nxt] == GRAY:
                    j = path.index(nxt)
                    return path[j:] + [nxt]
            else:
                color[node] = BLACK
                path.pop()
                idx_stack.pop()
    return None


