    graph = {n: set(deps.get(n, [])) for n in nodes}

    # Reverse edges: for each package, which packages depend on it.
    dependents = {n: [] for n in nodes}
    for n, ds in graph.items():
        for d in ds:
            dependents[d].append(n)

    # Number of dependencies not yet placed.
    remaining = {n: len(ds) for n, ds in graph.items()}

    # Min-heap of packages whose dependencies are all placed.
    heap = [n for n in nodes if remaining[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for p in dependents[n]:
            remaining[p] -= 1
            if remaining[p] == 0:
                heapq.heappush(heap, p)

    if len(order) != len(nodes):
        cycle = _find_cycle({n: sorted(ds) for n, ds in graph.items()})
        raise CycleError(cycle)

