import heapq


class CycleError(Exception):
    def __init__(self, cycle):
        super().__init__("dependency cycle: " + " -> ".join(cycle))
        self.cycle = cycle


def topo_order(deps: dict[str, list[str]]) -> list[str]:
    # Build a normalized graph: every package (including dependency-only ones)
    # maps to the set of distinct packages it directly depends on.
    graph: dict[str, set[str]] = {}
    for pkg, dep_list in deps.items():
        graph.setdefault(pkg, set())
        for d in dep_list:
            graph[pkg].add(d)
            graph.setdefault(d, set())

    # Kahn's algorithm with a min-heap for lexicographically smallest order.
    indeg = {p: len(ds) for p, ds in graph.items()}
    dependents: dict[str, list[str]] = {p: [] for p in graph}
    for p, ds in graph.items():
        for d in ds:
            dependents[d].append(p)

    heap = [p for p in graph if indeg[p] == 0]
    heapq.heapify(heap)

    order: list[str] = []
    while heap:
        p = heapq.heappop(heap)
        order.append(p)
        for q in dependents[p]:
            indeg[q] -= 1
            if indeg[q] == 0:
                heapq.heappush(heap, q)

    if len(order) == len(graph):
        return order

    # Some packages were never placed; each one has an unplaced dependency.
    # Walk along unplaced dependencies until a package repeats to find a cycle.
    remaining = {p for p in graph if indeg[p] > 0}
    cur = min(remaining)
    path: list[str] = []
    index: dict[str, int] = {}
    while cur not in index:
        index[cur] = len(path)
        path.append(cur)
        cur = min(d for d in graph[cur] if d in remaining)

    cycle = path[index[cur]:] + [cur]
    raise CycleError(cycle)
