        self._text = ""
        self._cursor = 0
        # Each entry: ((text, cursor) before the edit, (text, cursor) after the edit)
        self._undo_stack = []
        self._redo_stack = []

    @property
    def text(self) -> str:
        return self._text

    @property
    def cursor(self) -> int:
        return self._cursor

    def _snapshot(self):
        return (self._text, self._cursor)

    def _restore(self, snap) -> None:
        self._text, self._cursor = snap

    def insert(self, s: str) -> None:
        before = self._snapshot()
        self._text = self._text[:self._cursor] + s + self._text[self._cursor:]
        self._cursor += len(s)
        after = self._snapshot()
        self._undo_stack.append((before, after))
        self._redo_stack.clear()

    def delete(self, n: int) -> None:
        if n <= 0 or self._cursor == 0:
            return
        count = min(n, self._cursor)
        before = self._snapshot()
        start = self._cursor - count
        self._text = self._text[:start] + self._text[self._cursor:]
        self._cursor = start
        after = self._snapshot()
        self._undo_stack.append((before, after))
        self._redo_stack.clear()

    def move(self, pos: int) -> None:
        self._cursor = max(0, min(pos, len(self._text)))

    def undo(self) -> bool:
        if not self._undo_stack:
            return False
        before, after = self._undo_stack.pop()
        self._restore(before)
        self._redo_stack.append((before, after))
        return True

    def redo(self) -> bool:
        if not self._redo_stack:
            return False
        before, after = self._redo_stack.pop()
        self._restore(after)
        self._undo_stack.append((before, after))
        return True
