_NUMERIC_IDENT_RE = re.compile(r"[0-9]+")
_NUMERIC_RE = re.compile(r"0|[1-9][0-9]*")


def _validate_identifiers(text: str, version: str, label: str) -> list:
    if text == "":
        raise ValueError(f"Invalid version {version!r}: empty {label}")
    idents = text.split(".")
    for ident in idents:
        if ident == "":
            raise ValueError(f"Invalid version {version!r}: empty identifier in {label}")
        if not _IDENT_RE.fullmatch(ident):
            raise ValueError(f"Invalid version {version!r}: bad character in {label}")
    return idents


def _parse(version: str):
    """Return a precedence key for a SemVer 2.0.0 version string.

    Raises ValueError if the version is invalid.
    """
    if not isinstance(version, str):
        raise ValueError(f"Invalid version {version!r}: not a string")

    main = version
    if "+" in main:
        main, build = main.split("+", 1)
        _validate_identifiers(build, version, "build metadata")

    pre = None
    if "-" in main:
        core, pre = main.split("-", 1)
    else:
        core = main

    match = _CORE_RE.fullmatch(core)
    if not match:
        raise ValueError(f"Invalid version {version!r}: malformed MAJOR.MINOR.PATCH")
    major, minor, patch = (int(g) for g in match.groups())

    if pre is None:
        pre_key = (1,)  # no prerelease: higher than any prerelease
    else:
        idents = _validate_identifiers(pre, version, "prerelease")
        ident_keys = []
        for ident in idents:
            if _NUMERIC_IDENT_RE.fullmatch(ident):
                if not _NUMERIC_RE.fullmatch(ident):
                    raise ValueError(
                        f"Invalid version {version!r}: leading zero in numeric prerelease identifier"
                    )
                ident_keys.append((0, int(ident)))  # numeric: lower than alphanumeric
            else:
                ident_keys.append((1, ident))  # alphanumeric: ASCII lexical order
        pre_key = (0, tuple(ident_keys))  # shorter list (prefix) is lower

    return ((major, minor, patch), pre_key)


