import re

_IDENT = r"[0-9A-Za-z-]+"
_NUMERIC_RE = re.compile(r"0|[1-9][0-9]*")
_VERSION_RE = re.compile(
    r"(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-(" + _IDENT + r"(?:\." + _IDENT + r")*))?"
    r"(?:\+(" + _IDENT + r"(?:\." + _IDENT + r")*))?"
)


def _parse(version: str):
    if not isinstance(version, str):
        raise ValueError(f"Invalid semantic version: {version!r}")
    m = _VERSION_RE.fullmatch(version)
    if m is None:
        raise ValueError(f"Invalid semantic version: {version!r}")

    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    prerelease = m.group(4)

    if prerelease is None:
        # A release (no prerelease) has higher precedence than any prerelease.
        return (major, minor, patch, 1, ())

    ids = []
    for ident in prerelease.split("."):
        if ident.isdigit() and all(c in "0123456789" for c in ident):
            if not _NUMERIC_RE.fullmatch(ident):
                raise ValueError(
                    f"Numeric prerelease identifier has leading zero: {version!r}"
                )
            # Numeric identifiers sort below alphanumeric ones.
            ids.append((0, int(ident), ""))
        else:
            # Alphanumeric identifiers compare lexically (ASCII).
            ids.append((1, 0, ident))
    # Tuple comparison: a shorter list that is a prefix of a longer one is lower.
    return (major, minor, patch, 0, tuple(ids))


