    ka = _parse(a)
    kb = _parse(b)
    if ka < kb:
        return -1
    if ka > kb:
        return 1
    return 0


def sort_versions(versions: list[str]) -> list[str]:
    keyed = [(_parse(v), v) for v in versions]
    # sorted() is stable, so equal-precedence versions keep input order.
    keyed.sort(key=lambda pair: pair[0])
    return [v for _, v in keyed]

